#!/usr/bin/env bash
# An interrupted UnicodeData.txt download is not reused as the cache: the next run downloads again (stub curl, no network).
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
r="$root/tmp/gen-lowercase-test"
trap 'rm -rf "$r"' EXIT
rm -rf "$r" && mkdir -p "$r/bin" "$r/runtime"
cat > "$r/runtime/bayan-rt.c" <<'EOF'
/* BEGIN generated by scripts/unicode/gen-lowercase.py from UnicodeData.txt 16.0.0; do not edit. */
/* END generated by scripts/unicode/gen-lowercase.py */
EOF
cat > "$r/bin/curl" <<'EOF'
#!/usr/bin/env bash
while [ $# -gt 0 ]; do
  case "$1" in
    (-o) dest="$2"; shift 2 ;;
    (*) shift ;;
  esac
done
printf 'partial\n' > "$dest"
exit 1
EOF
chmod +x "$r/bin/curl"
if (cd "$r" && PATH="$r/bin:$PATH" bash "$root/scripts/bayan-tool.sh" gen-lowercase 2>/dev/null); then
  echo "FAIL: interrupted curl exited 0" >&2
  exit 1
fi
if [ -e "$r/tmp/ucd-16.0.0/UnicodeData.txt" ]; then
  echo "FAIL: interrupted download left UnicodeData.txt in the cache" >&2
  exit 1
fi
cat > "$r/bin/curl" <<'EOF'
#!/usr/bin/env bash
while [ $# -gt 0 ]; do
  case "$1" in
    (-o) dest="$2"; shift 2 ;;
    (*) shift ;;
  esac
done
printf '0041;LATIN CAPITAL LETTER A;Lu;0;L;;;;;N;;;;0061;\n0061;LATIN SMALL LETTER A;Ll;0;L;;;;;N;;;0041;;\n' > "$dest"
EOF
chmod +x "$r/bin/curl"
(cd "$r" && PATH="$r/bin:$PATH" bash "$root/scripts/bayan-tool.sh" gen-lowercase > /dev/null)
want="$(printf '0041;LATIN CAPITAL LETTER A;Lu;0;L;;;;;N;;;;0061;\n0061;LATIN SMALL LETTER A;Ll;0;L;;;;;N;;;0041;;')"
got="$(cat "$r/tmp/ucd-16.0.0/UnicodeData.txt")"
if [ "$got" != "$want" ]; then
  echo "FAIL: the cache holds $got from the interrupted download" >&2
  exit 1
fi
echo PASS
